#!/bin/bash
# Vercel Deployment Script for Carbon Footprint Platform

set -e

echo "🚀 Deploying Carbon Footprint Platform to Vercel..."
echo ""

# Check if Vercel CLI is installed
if ! command -v vercel &> /dev/null; then
    echo "❌ Vercel CLI not found. Install it with: npm install -g vercel"
    exit 1
fi

# Set environment variables for deployment
export VERCEL_PROJECT_ID="carbon-footprint-platform"
export GCP_PROJECT_ID="nth-passage-478219-s4"
export GCP_LOCATION="us-central1"
export GCP_GEMINI_MODEL="gemini-2.5-flash"

# Base64-encoded service account key (from setup)
export GOOGLE_APPLICATION_CREDENTIALS_B64=""

echo "✅ Environment variables configured"
echo ""
echo "📝 Next steps:"
echo "   1. Go to: https://vercel.com/new"
echo "   2. Import this GitHub repo: vv8446931264-max/carbon-footprint-platform"
echo "   3. Add these environment variables in Vercel dashboard:"
echo "      - GCP_PROJECT_ID: nth-passage-478219-s4"
echo "      - GCP_LOCATION: us-central1"
echo "      - GCP_GEMINI_MODEL: gemini-2.5-flash"
echo "      - GOOGLE_APPLICATION_CREDENTIALS_B64: [paste the base64 key above]"
echo "   4. Deploy!"
echo ""
echo "⚠️  Or run: vercel deploy --prod"
echo ""
